-- A target whose transfer the relay recorded as aborted releases its staged
-- import content and projection. Nothing was published: a published target only
-- ends committed. The transfer, preparation and import rows remain as
-- tombstones, so the attempt can neither resume nor be reused.
CREATE VIEW connect_aborted_targets AS SELECT t.transfer_id,t.inactive_import_id AS import_id
 FROM connect_transfers t
 WHERE t.local_role='target' AND t.restore_hold=0 AND t.resolution='aborted' AND t.terminal_outcome='aborted'
 AND t.terminal_fingerprint IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM connect_preparations p WHERE p.transfer_id=t.transfer_id AND p.phase='published');
DROP TRIGGER connect_display_delete;
CREATE TRIGGER connect_display_delete BEFORE DELETE ON connect_projection_display WHEN NOT EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE transfer_id=OLD.transfer_id AND stage='before') AND NOT EXISTS(SELECT 1 FROM connect_aborted_targets WHERE transfer_id=OLD.transfer_id) BEGIN SELECT RAISE(ABORT,'connect_projection_immutable'); END;
DROP TRIGGER connect_projection_messages_delete;
CREATE TRIGGER connect_projection_messages_delete BEFORE DELETE ON connect_projection_messages WHEN EXISTS(SELECT 1 FROM connect_preparations WHERE transfer_id=OLD.transfer_id AND phase<>'preparing') AND NOT EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE transfer_id=OLD.transfer_id AND stage='before') AND NOT EXISTS(SELECT 1 FROM connect_aborted_targets WHERE transfer_id=OLD.transfer_id) BEGIN SELECT RAISE(ABORT,'connect_projection_immutable'); END;
