CREATE TRIGGER connect_projection_citations_delete BEFORE DELETE ON connect_projection_citations WHEN EXISTS(SELECT 1 FROM connect_preparations WHERE transfer_id=OLD.transfer_id AND phase<>'preparing') AND NOT EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE transfer_id=OLD.transfer_id AND stage='before') AND NOT EXISTS(SELECT 1 FROM connect_aborted_targets WHERE transfer_id=OLD.transfer_id) BEGIN SELECT RAISE(ABORT,'connect_projection_immutable'); END;
