DROP TRIGGER connect_records_delete;
CREATE TRIGGER connect_records_delete BEFORE DELETE ON e_inactive_records WHEN EXISTS(SELECT 1 FROM connect_transfers WHERE inactive_import_id=OLD.import_id) AND NOT EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE import_id=OLD.import_id AND stage='before') AND NOT EXISTS(SELECT 1 FROM connect_aborted_targets WHERE import_id=OLD.import_id) BEGIN SELECT RAISE(ABORT,'connect_transfer_leased'); END;
DROP TRIGGER connect_fragments_delete;
CREATE TRIGGER connect_fragments_delete BEFORE DELETE ON e_inactive_fragments WHEN EXISTS(SELECT 1 FROM connect_transfers WHERE inactive_import_id=OLD.import_id) AND NOT EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE import_id=OLD.import_id AND stage='before') AND NOT EXISTS(SELECT 1 FROM connect_aborted_targets WHERE import_id=OLD.import_id) BEGIN SELECT RAISE(ABORT,'connect_transfer_leased'); END;
DROP TRIGGER connect_mapping_delete;
CREATE TRIGGER connect_mapping_delete BEFORE DELETE ON e_inactive_mapping WHEN EXISTS(SELECT 1 FROM connect_transfers WHERE inactive_import_id=OLD.import_id) AND NOT EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE import_id=OLD.import_id AND stage='before') AND NOT EXISTS(SELECT 1 FROM connect_aborted_targets WHERE import_id=OLD.import_id) BEGIN SELECT RAISE(ABORT,'connect_transfer_leased'); END;
DROP TRIGGER connect_import_shrink;
CREATE TRIGGER connect_import_shrink BEFORE UPDATE ON e_inactive_imports WHEN EXISTS(SELECT 1 FROM connect_transfers WHERE inactive_import_id=OLD.id) AND (NEW.id<>OLD.id OR NEW.identity_key<>OLD.identity_key OR NEW.begin_json<>OLD.begin_json OR NEW.phase>2 OR NEW.charge_bytes<OLD.charge_bytes OR NEW.received_bytes<OLD.received_bytes OR NEW.next_record<OLD.next_record) AND NOT (NEW.charge_bytes<=OLD.charge_bytes AND NEW.id IS OLD.id AND NEW.identity_key IS OLD.identity_key AND NEW.begin_json IS OLD.begin_json AND NEW.phase IS OLD.phase AND NEW.revision IS OLD.revision AND NEW.next_record IS OLD.next_record AND NEW.received_bytes IS OLD.received_bytes AND NEW.created_at IS OLD.created_at AND NEW.progressed_at IS OLD.progressed_at AND NEW.expires_at IS OLD.expires_at AND NEW.idle_ms IS OLD.idle_ms AND NEW.last_clock IS OLD.last_clock AND NEW.mapping_hash IS OLD.mapping_hash AND (EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE import_id=OLD.id AND stage='before') OR EXISTS(SELECT 1 FROM connect_aborted_targets WHERE import_id=OLD.id))) BEGIN SELECT RAISE(ABORT,'connect_transfer_leased'); END;
DROP TRIGGER connect_archive_e_inactive_imports_update;
CREATE TRIGGER connect_archive_e_inactive_imports_update BEFORE UPDATE ON e_inactive_imports WHEN EXISTS(SELECT 1 FROM connect_preparations WHERE import_id=OLD.id) AND NOT (NEW.charge_bytes<=OLD.charge_bytes AND NEW.id IS OLD.id AND NEW.identity_key IS OLD.identity_key AND NEW.begin_json IS OLD.begin_json AND NEW.phase IS OLD.phase AND NEW.revision IS OLD.revision AND NEW.next_record IS OLD.next_record AND NEW.received_bytes IS OLD.received_bytes AND NEW.created_at IS OLD.created_at AND NEW.progressed_at IS OLD.progressed_at AND NEW.expires_at IS OLD.expires_at AND NEW.idle_ms IS OLD.idle_ms AND NEW.last_clock IS OLD.last_clock AND NEW.mapping_hash IS OLD.mapping_hash AND (EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE import_id=OLD.id AND stage='before') OR EXISTS(SELECT 1 FROM connect_aborted_targets WHERE import_id=OLD.id))) BEGIN SELECT RAISE(ABORT,'connect_archive_immutable'); END;
DROP TRIGGER connect_preparation_metadata;
CREATE TRIGGER connect_preparation_metadata BEFORE UPDATE ON connect_preparations WHEN OLD.phase<>'preparing' AND (NEW.transfer_id IS NOT OLD.transfer_id OR NEW.canonical_import_id IS NOT OLD.canonical_import_id OR NEW.target_conversation_id IS NOT OLD.target_conversation_id OR NEW.import_id IS NOT OLD.import_id OR NEW.import_revision IS NOT OLD.import_revision OR NEW.lineage_id IS NOT OLD.lineage_id OR NEW.raw_manifest IS NOT OLD.raw_manifest OR NEW.portable_manifest IS NOT OLD.portable_manifest OR NEW.storage_manifest IS NOT OLD.storage_manifest OR NEW.mapping_hash IS NOT OLD.mapping_hash OR NEW.local_generation IS NOT OLD.local_generation OR NEW.source_generation IS NOT OLD.source_generation OR NEW.target_generation IS NOT OLD.target_generation OR NEW.configuration_digest IS NOT OLD.configuration_digest OR NEW.preparators_digest IS NOT OLD.preparators_digest OR NEW.prepared_digest IS NOT OLD.prepared_digest OR NEW.projection_hash IS NOT OLD.projection_hash OR NEW.preparation_revision IS NOT OLD.preparation_revision OR NEW.provider_id IS NOT OLD.provider_id OR NEW.model_id IS NOT OLD.model_id OR NEW.reasoning_effort IS NOT OLD.reasoning_effort OR (NEW.title IS NOT OLD.title AND NOT(NEW.title='' AND (EXISTS(SELECT 1 FROM connect_deleting_transfers WHERE transfer_id=OLD.transfer_id AND stage='before') OR EXISTS(SELECT 1 FROM connect_aborted_targets WHERE transfer_id=OLD.transfer_id)))) OR NEW.created_at IS NOT OLD.created_at OR NEW.message_count IS NOT OLD.message_count OR NEW.citation_count IS NOT OLD.citation_count OR NEW.asset_count IS NOT OLD.asset_count OR NEW.fingerprint IS NOT OLD.fingerprint) BEGIN SELECT RAISE(ABORT,'connect_preparation_immutable'); END;
